<?php require_once '../config/db.php'; require_once '../includes/auth.php'; require_role('student');
$st=$pdo->prepare("SELECT d.downloaded_at,m.title,m.file_name,s.name subject_name FROM downloads d JOIN materials m ON m.id=d.material_id JOIN subjects s ON s.id=m.subject_id WHERE d.user_id=? ORDER BY d.id DESC");$st->execute([$_SESSION['user_id']]);$rows=$st->fetchAll();
$page_title='Downloads';$css_path='../assets/css/style.css';$home_path='dashboard.php';$logout_path='../logout.php';$role='student';include '../includes/header.php';?><div class="layout"><?php include '../includes/sidebar.php';?><h1 class="page-title">Downloads</h1><div class="table-card"><table><thead><tr><th>Material</th><th>Subject</th><th>Downloaded On</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['subject_name'])?></td><td><?=date('d M Y H:i',strtotime($r['downloaded_at']))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="3" class="empty">No downloads yet.</td></tr><?php endif;?></tbody></table></div></main></div><?php include '../includes/footer.php';?>